pub fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n < 4 {
                4 - n
            } else {
                // for n >= 4, we need to add 1 if n is odd, 0 if even
                n % 2
            }
        })
        .collect()
}

